Translate("ptBR", "eitrigg", {
	title = "Eitrigg",
	subtitle = "Conselheiro do Chefe Guerreiro",
	found = "Grommash Hold",
	hint = [=[Fale com o velho guerreiro que aconselha o Chefe Guerreiro em Grommash Hold.]=],
	allegiance = "Horda · clã Rocha Negra (outrora)",
	sections = {
		{
			title = "Resumo",
			text = [=[Eitrigg é um velho guerreiro {link:orcs}orc{/link} do {link:blackrock-clan}clã Rocha Negra{/link} que serve a {link:thrall}Thrall{/link} como conselheiro e supervisor dos recrutas da {link:horde}Horda{/link}. Lutou nas guerras da antiga Horda sob Blackhand e Doomhammer. Passou a odiar os adoradores de demônios que desviaram seu povo e, por um tempo, deixou a Horda de todo. Voltou quando ouviu a visão de Thrall de uma Horda guiada por xamãs em vez de demônios.]=],
		},
		{
			title = "Importância",
			text = [=[Eitrigg é uma ponte entre a antiga {link:horde}Horda{/link} e a nova. Conhece os costumes dos {link:blackrock-mountain}Rocha Negra{/link} melhor que qualquer {link:orcs}orc{/link} em {link:orgrimmar}Orgrimmar{/link}, e sabe quanto custa abandoná-los.]=],
		},
		{
			title = "Feitos",
			text = [=[• Serviu como tenente do chefe guerreiro dos {link:blackrock-mountain}Rocha Negra{/link} nos dias anteriores ao {link:dark-portal}Portal Negro{/link}, ao lado de {link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• Vigiou a assassina {link:garona}Garona{/link} na {link:second-war}Segunda Guerra{/link}, e a deixou partir quando ela fugiu.
• Deixou a {link:horde}Horda{/link} e vagou para o norte, pelas terras dos humanos, onde foi feito prisioneiro e salvo pelo Chefe Guerreiro.
• Supervisiona o treinamento dos novos recrutas para {link:thrall}Thrall{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Rend Vive",
			hint = "Leve a Eitrigg notícias dos Rocha Negra.",
			text = [=[A notícia veio dos {link:badlands}Ermos{/link}: Rend Blackhand, filho do antigo Chefe Guerreiro Blackhand, estava vivo e reunia o {link:blackrock-clan}clã Rocha Negra{/link} no Pico da {link:blackrock-mountain}Rocha Negra{/link}. Pensava-se que Rend fora morto havia muito tempo. Ninguém em {link:orgrimmar}Orgrimmar{/link} conhecia os Rocha Negra como Eitrigg, e ninguém tinha mais direito à vingança. Ele passou a notícia a {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "A Cabeça de Rend",
			hint = "Leve a cabeça de Rend Blackhand ao Chefe Guerreiro.",
			text = [=[Quando a cabeça de Rend foi posta diante do Chefe Guerreiro, Eitrigg viu quebrada a última sombra do clã a que um dia servira. Os {link:blackrock-mountain}Rocha Negra{/link} mergulharam no caos mais uma vez. Para o velho guerreiro, foi uma dívida saldada.]=],
		},
	},
	mentions = {
		{ text = "A Nova {link:horde}Horda{/link}" },
		{ text = "A Sabedoria de Eitrigg" },
		{ text = "Pela {link:horde}Horda{/link}!" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu Chefe Guerreiro e salvador" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "seu velho camarada" },
		{ id = "vol-jin", name = "Vol'jin", note = "um colega conselheiro" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "o humano que o salvou" },
	},
})

Translate("ptBR", "neeru-fireblade", {
	title = "Neeru Fireblade",
	subtitle = "Bruxo do Cleft of Shadow",
	found = "Sua tenda no Cleft of Shadow",
	hint = "Procure o bruxo cuja tenda fica no Cleft of Shadow.",
	allegiance = "Horda (declarada)",
	aliases = { "Neeru" },
	sections = {
		{
			title = "Resumo",
			text = [=[Neeru Fireblade é um bruxo que vive no {link:cleft-of-shadow}Cleft of Shadow{/link}. Poucos orcs confiam nos de sua espécie, pois foram os bruxos que primeiro prenderam os orcs aos demônios. Neeru diz usar suas artes apenas contra os demônios. Desde a última guerra, diz ele, tem buscado cada vestígio de corrupção demoníaca na sociedade {link:orcs}orc{/link}, e serve ao Chefe Guerreiro erradicando os cultos que se escondem em sua cidade.]=],
		},
		{
			title = "Importância",
			text = [=[Neeru está no centro da luta contra a {link:burning-blade}Lâmina Ardente{/link}. Cada fio do culto em {link:durotar}Durotar{/link} parece levar de volta ao {link:cleft-of-shadow}Cleft of Shadow{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estuda as coleiras abrasadoras da {link:burning-blade}Lâmina Ardente{/link}.
• Ordena a destruição da Semente Demoníaca, um objeto de poder demoníaco, no {link:dreadmist-peak}Morro de Brumedo{/link}, nos {link:the-barrens}Sertões{/link}.
• Envia heróis às {link:ragefire-chasm}Cavernas Ígneas{/link} para matar o guarda vil {link:taragaman-the-hungerer}Taragaman{/link}.
• Troca ervas com o médico bruxo {link:witch-doctor-uzer-i}Uzer'i{/link}, de {link:feralas}Feralas{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Coleira Abrasadora",
			hint = "Leve uma coleira abrasadora de Margoz ao Cleft of Shadow.",
			text = [=[Quando {link:margoz}Margoz{/link} lhe enviou uma coleira abrasadora, Neeru a examinou de perto. Nomeou o culto que a fez, a {link:burning-blade}Lâmina Ardente{/link}, e o objeto de poder em torno do qual ele se reúne: a Semente Demoníaca. Queria que ela fosse destruída.]=],
		},
		{
			title = "A Semente Demoníaca",
			hint = "Destrua a Semente Demoníaca no alto do Morro de Brumedo.",
			text = [=[O assistente de Neeru, Ak'Zeloth, preparou pedras para romper o vínculo da Semente com a Legião. Quando a Semente foi destruída, ondas de poder atravessaram o éter. Ak'Zeloth as sentiu, e advertiu que outros também as tinham sentido.]=],
		},
		{
			title = "Lealdades Verdadeiras",
			hint = "Descubra o que o Chefe Guerreiro sabe sobre Neeru.",
			text = [=[Neeru é o líder secreto da {link:burning-blade}Lâmina Ardente{/link} e um servo do {link:shadow-council}Conselho das Sombras{/link}. Acredita que {link:thrall}Thrall{/link} é um tolo que confia nele. Está enganado: o Chefe Guerreiro sabe, e o deixa viver porque ele é útil. Neeru envia os seguidores leais de Thrall para morrer nas {link:ragefire-chasm}Cavernas Ígneas{/link}, e põe à prova a Searing Blade para ver quais de seus membros são dignos. Quando um jovem tenente da Lâmina veio a ele com a insígnia certa, Neeru acolheu um espião.]=],
		},
		{
			title = "O Faminto",
			hint = "Mate o guarda vil que lidera a Searing Blade.",
			text = [=[Neeru apontou o guarda vil {link:taragaman-the-hungerer}Taragaman, o Faminto{/link}, como o senhor da Searing Blade e pediu seu coração, para agradar ao Chefe Guerreiro. A Searing Blade era descartável para ele. Só dois de seus líderes importavam, e não eram o guarda vil.]=],
		},
	},
	mentions = {
		{ text = "Neeru Fireblade" },
		{ text = "Sombras Ardentes" },
		{ text = "Ak'Zeloth" },
		{ text = "A Semente Demoníaca" },
		{ text = "Inimigos Ocultos" },
		{ text = "Matando a Fera" },
		{ text = "Um Pedido Estranho" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "o Chefe Guerreiro que o vigia" },
		{ id = "margoz", name = "Margoz", note = "enviou-lhe uma coleira" },
		{ id = "gazz-uz", name = "Gazz'uz", note = "um servo da Lâmina" },
		{ id = "taragaman-the-hungerer", name = "Taragaman, o Faminto", note = "o guarda vil que ele entregou" },
	},
})

